export function exhibitionTargetIsNear(position, viewingPosition, { moving = false, radius = 1.8 } = {}) {
  if (moving || !viewingPosition) return false;
  // Proximity belongs to the visitor's planned standing position. A tall
  // cabinet and a wall label can have very different anchor heights.
  return Math.hypot(position.x - viewingPosition[0], position.z - viewingPosition[2]) <= radius;
}

// Walking through a room or corridor does not select its introduction. Only
// arriving at a reading position while facing its exhibit changes the narrative.
export function exhibitionWalkingTarget(exhibition, position, yaw) {
  const targets = [
    { ...exhibition.architecture.entrance, index: -1, roomIndex: -1 },
    ...exhibition.rooms.map(room => ({ eye: room.introEye, anchor: room.introAnchor, index: -1, roomIndex: room.index })),
    ...exhibition.stops,
    ...(exhibition.closing ? [{ ...exhibition.closing, index: -2, roomIndex: exhibition.rooms.length - 1 }] : []),
    ...(exhibition.citations ? [{ ...exhibition.citations, index: -4, roomIndex: exhibition.rooms.length - 1 }] : []),
  ];
  let nearest = null, distance = Infinity;
  for (const target of targets) {
    if (!exhibitionTargetIsNear(position, target.eye)) continue;
    const dx = target.anchor[0] - position.x, dz = target.anchor[2] - position.z;
    const facing = (-Math.sin(yaw) * dx - Math.cos(yaw) * dz) / Math.max(.1, Math.hypot(dx, dz));
    if (facing < .65) continue;
    const d = Math.hypot(position.x - target.eye[0], position.z - target.eye[2]);
    if (d < distance) { nearest = { index: target.index, roomIndex: target.roomIndex }; distance = d; }
  }
  return nearest;
}

export function pickExhibitionTarget(raycaster, targets, walls) {
  // Pointer ownership follows the rendered surface, including its current
  // transform. Invisible envelopes must never extend a work's interaction area.
  const isVisible = mesh => { for (let node = mesh; node; node = node.parent) if (node.visible === false) return false; return mesh.material?.visible !== false; };
  const picked = raycaster.intersectObjects(targets.filter(isVisible), false)[0];
  if (!picked) return undefined;
  const wall = raycaster.intersectObjects(walls, false)[0];
  if (wall && wall.distance < picked.distance - .02) return undefined;
  return picked.object.userData;
}
